import json,time,re,bisect,collections
from pathlib import Path
p=Path(__file__).parent
entries=[]
for line in (p/'managed-perf.map').read_text().splitlines():
 a,n,name=line.split(' ',2);entries.append((int(a,16),int(n,16),name))
entries.sort();addresses=[x[0] for x in entries]
def mapped(addr):
 i=bisect.bisect_right(addresses,addr)-1
 return entries[i][2] if i>=0 and addr<entries[i][0]+entries[i][1] else None
rows=[json.loads(x) for x in next((p/'run/logs').glob('*/process.jsonl')).read_text().splitlines() if x.strip()]
start=next(r['Time']/1000 for r in rows if 'POWER_ROUTE_PORTFOLIO start ' in r.get('Message',''))
end=next(r['Time']/1000 for r in rows if 'POWER_ROUTE_PORTFOLIO result ' in r.get('Message',''))
offsets=[time.time()-time.monotonic() for _ in range(7)];offset=min(offsets)
scopes={name:{'count':0,'cycles':0,'leaf':collections.Counter(),'nativeNearestManaged':collections.Counter(),'dsos':collections.Counter(),'inclusive':collections.Counter()} for name in ('all-process','opening-power-approx')}
header=re.compile(r'\s*([0-9.]+):\s+(\d+)');frame=re.compile(r'\s+([0-9a-fA-F]+)\s+\((.*)\)');ts=0;period=0;frames=[]
def flush():
 if not frames:return
 resolved=[mapped(a) if 'doublemapper' in d or d=='[unknown]' else None for a,d in frames]
 leaf=resolved[0] or frames[0][1]
 nearest=next((n for n in resolved[1:] if n and not n.startswith('stub')),None)
 for name,s in scopes.items():
  if name=='opening-power-approx' and not start<=ts+offset<=end:continue
  s['count']+=1;s['cycles']+=period;s['leaf'][leaf]+=period;s['dsos'][frames[0][1]]+=period
  if not resolved[0]:s['nativeNearestManaged'][nearest or '(unresolved)']+=period
  for n in set(n for n in resolved if n):s['inclusive'][n]+=period
with (p/'stacks.txt').open() as f:
 for line in f:
  m=header.match(line)
  if m:flush();ts=float(m[1]);period=int(m[2]);frames=[]
  else:
   m=frame.match(line)
   if m:frames.append((int(m[1],16),m[2]))
flush()
out={'scopeNote':'Hardware cycles:u, fp callchains. Period weighted leaf CPU samples; inclusive frames overlap and are not summed. Diagnostic only, not performance acceptance. Opening power window uses post-run realtime-monotonic conversion; phase boundaries approximate. Native nearest caller does not identify allocation operation or inclusive CPU of full method.','currentRealtimeMinusMonotonic':offset,'openingPowerLogEpoch':[start,end],'runtimeFromSampleDso':'Microsoft.NETCore.App/9.0.20','scopes':{}}
for name,s in scopes.items():
 o={k:v for k,v in s.items() if isinstance(v,int)}
 for k,v in s.items():
  if isinstance(v,collections.Counter):o[k]=[{'name':n,'estimatedCycles':c,'fraction':c/s['cycles']} for n,c in v.most_common(70)]
 out['scopes'][name]=o
 print(name,'samples',s['count'],'estimated cycles',s['cycles'])
 for n,c in s['leaf'].most_common(18):print(f'{100*c/s["cycles"]:.3f}%',n)
 print('nativeNearestManaged')
 for n,c in s['nativeNearestManaged'].most_common(10):print(f'{100*c/s["cycles"]:.3f}%',n)
(p/'cpu-analysis.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')

