using ICSharpCode.Decompiler;
using ICSharpCode.Decompiler.CSharp;
using ICSharpCode.Decompiler.TypeSystem;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using var stream = File.OpenRead(args[0]);
using var pe = new PEReader(stream);
var reader = pe.GetMetadataReader();
var decompiler = new CSharpDecompiler(args[0], new DecompilerSettings { ThrowOnAssemblyResolveErrors = false });
foreach (var name in args.Skip(1))
{
    var match = reader.TypeDefinitions.Select(reader.GetTypeDefinition)
        .Where(t => reader.GetString(t.Name) == name).ToArray();
    if (match.Length != 1) throw new InvalidDataException($"Expected one native type named {name}; found {match.Length}.");
    var qualified = reader.GetString(match[0].Namespace) + "." + name;
    var source = decompiler.DecompileTypeAsString(new FullTypeName(qualified));
    if (source.Length == 0) throw new InvalidDataException("No decompiled body: " + qualified);
    File.WriteAllText(Path.Combine(AppContext.BaseDirectory, name + ".cs.txt"), source);
    Console.WriteLine(qualified);
}
